import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

const wensityCardSurfaceClass = cn(
  "relative isolate overflow-hidden rounded-2xl",
  "border border-black/[0.08] bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#ffffff_0%,#f4f4f5_72%)] [box-shadow:0_1px_2px_rgba(0,0,0,.06),0_8px_24px_-12px_rgba(0,0,0,.08)]",
  "dark:border-white/[0.06] dark:bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#15151b_0%,#0a0a0b_72%)] dark:[box-shadow:0_1px_2px_rgba(0,0,0,.4),0_8px_24px_-12px_rgba(0,0,0,.6)]",
);

export type ToggleVariant = "default" | "icon" | "outline" | "soft";
export type ToggleSize = "sm" | "md" | "lg";

export interface ToggleProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  variant?: ToggleVariant;
  size?: ToggleSize;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
}

export interface ToggleGroupProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> {
  type?: "single" | "multiple";
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  variant?: ToggleVariant;
  size?: ToggleSize;
  orientation?: "horizontal" | "vertical";
  disabled?: boolean;
  children: React.ReactNode;
}

export interface ToggleGroupItemProps
  extends Omit<ToggleProps, "pressed" | "defaultPressed" | "onPressedChange"> {
  value: string;
}

type ToggleGroupContextValue = {
  type: "single" | "multiple";
  value: string | string[] | undefined;
  setValue: (itemValue: string) => void;
  variant: ToggleVariant;
  size: ToggleSize;
  disabled?: boolean;
  segmented: boolean;
};

const ToggleGroupContext = React.createContext<ToggleGroupContextValue | null>(
  null,
);

const EASE_OUT_CSS = "cubic-bezier(0.23, 1, 0.32, 1)";
const EASE_DRAWER_CSS = "cubic-bezier(0.32, 0.72, 0, 1)";
const TOGGLE_STYLE_ID = "wensity-toggle-styles-v1";

const base = cn(
  "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-[10px] border border-transparent",
  "text-sm font-medium leading-none tracking-[-0.01em] select-none touch-manipulation",
  "transition-[background-color,border-color,color,opacity,box-shadow] duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
  "motion-reduce:transition-[background-color,border-color,color,opacity,box-shadow]",
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
  "disabled:pointer-events-none disabled:opacity-45",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
);

const sizes: Record<ToggleSize, string> = {
  sm: "h-8 gap-1.5 px-3 text-xs [&_svg]:size-3.5",
  md: "h-9 gap-2 px-3.5 [&_svg]:size-4",
  lg: "h-10 gap-2 px-4 text-[15px] [&_svg]:size-[18px]",
};

const iconSizes: Record<ToggleSize, string> = {
  sm: "size-8 gap-0 p-0 [&_svg]:size-3.5",
  md: "size-9 gap-0 p-0 [&_svg]:size-4",
  lg: "size-10 gap-0 p-0 [&_svg]:size-[18px]",
};

const offDefault = cn(
  "border border-transparent bg-transparent text-[var(--muted-foreground)]",
  "hover:border-[color-mix(in_srgb,var(--foreground)_10%,transparent)]",
  "hover:bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))]",
  "hover:text-[var(--foreground)]",
  "dark:hover:border-white/10 dark:hover:bg-white/[0.06] dark:hover:text-[#f5f6f2]",
);

const onDefault = cn(
  "border border-[#31383d] bg-[#24292d] text-white",
  "shadow-[0_1px_2px_rgba(0,0,0,0.10)]",
  "dark:border-white/18 dark:bg-[#f5f3ee] dark:text-[#151719]",
  "dark:shadow-[0_1px_2px_rgba(0,0,0,0.32)]",
);

const offOutline = cn(
  "border border-[var(--border-strong)] bg-transparent text-[var(--muted-foreground)]",
  "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)]",
  "hover:bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))]",
  "hover:text-[var(--foreground)]",
  "dark:hover:border-white/14 dark:hover:bg-white/[0.05]",
);

const onOutline = cn(
  "border-[color-mix(in_srgb,var(--foreground)_22%,transparent)]",
  "bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
  "text-[var(--foreground)]",
  "shadow-[0_1px_2px_rgba(0,0,0,0.05)]",
  "dark:border-white/16 dark:bg-[color-mix(in_srgb,var(--foreground)_12%,var(--background))]",
  "dark:shadow-[0_1px_2px_rgba(0,0,0,0.28)]",
);

const offSoft = cn(
  "border border-transparent",
  "bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))]",
  "text-[var(--muted-foreground)]",
  "hover:bg-[color-mix(in_srgb,var(--foreground)_8%,var(--background))]",
  "hover:text-[var(--foreground)]",
  "dark:bg-[color-mix(in_srgb,var(--foreground)_8%,var(--background))]",
  "dark:hover:bg-[color-mix(in_srgb,var(--foreground)_12%,var(--background))]",
);

const onSoft = cn(
  "border border-[color-mix(in_srgb,var(--foreground)_12%,transparent)]",
  "bg-[color-mix(in_srgb,var(--foreground)_11%,var(--background))]",
  "text-[var(--foreground)]",
  "shadow-[0_1px_2px_rgba(0,0,0,0.05)]",
  "dark:border-white/12 dark:bg-[color-mix(in_srgb,var(--foreground)_18%,var(--background))]",
  "dark:shadow-[0_1px_2px_rgba(0,0,0,0.30)]",
);

const variantOff: Record<ToggleVariant, string> = {
  default: offDefault,
  icon: offDefault,
  outline: offOutline,
  soft: offSoft,
};

const variantOn: Record<ToggleVariant, string> = {
  default: onDefault,
  icon: onDefault,
  outline: onOutline,
  soft: onSoft,
};

const groupItemBase = cn(
  "relative z-[1] rounded-lg",
  "data-[segmented=true]:border-transparent data-[segmented=true]:bg-transparent",
  "data-[segmented=true]:shadow-none",
  "data-[segmented=true]:hover:border-transparent",
  "data-[segmented=true][data-state=on]:border-transparent",
  "data-[segmented=true][data-state=on]:bg-transparent",
  "data-[segmented=true][data-state=on]:text-[var(--foreground)]",
  "data-[segmented=true][data-state=on]:shadow-none",
);

function ensureToggleStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(TOGGLE_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = TOGGLE_STYLE_ID;
  style.textContent = `
    [data-slot="toggle-segment-indicator"] {
      transform: translate3d(0, 0, 0);
      transition: transform 260ms ${EASE_DRAWER_CSS};
    }

    [data-slot="toggle-segment-indicator"][data-orientation="vertical"] {
      transition-duration: 240ms;
    }

    [data-slot="toggle-group-item"][data-segmented="true"] {
      transition: color 200ms ${EASE_OUT_CSS};
    }

    @media (prefers-reduced-motion: reduce) {
      [data-slot="toggle-segment-indicator"],
      [data-slot="toggle-group-item"][data-segmented="true"] {
        transition-duration: 0ms !important;
      }
    }
  `;
  document.head.appendChild(style);
}

function resolveSizeClasses(variant: ToggleVariant, size: ToggleSize) {
  return variant === "icon" ? iconSizes[size] : sizes[size];
}

export function toggleVariants({
  variant = "default",
  size = "md",
  pressed = false,
  segmented = false,
  className,
}: {
  variant?: ToggleVariant;
  size?: ToggleSize;
  pressed?: boolean;
  segmented?: boolean;
  className?: string;
} = {}) {
  return cn(
    base,
    resolveSizeClasses(variant, size),
    segmented ? null : pressed ? variantOn[variant] : variantOff[variant],
    segmented && "text-[var(--muted-foreground)] hover:text-[var(--foreground)]",
    segmented && pressed && "text-[var(--foreground)]",
    className,
  );
}

function getSegmentIndex(children: React.ReactNode, selectedValue?: string) {
  const values = React.Children.toArray(children)
    .map((child) => {
      if (!React.isValidElement(child)) return undefined;
      const props = child.props as { value?: string };
      return typeof props.value === "string" ? props.value : undefined;
    })
    .filter((value): value is string => value !== undefined);

  const selectedIndex = values.findIndex((value) => value === selectedValue);
  return {
    count: values.length,
    index: selectedIndex >= 0 ? selectedIndex : 0,
  };
}

function useToggleGroupContext(component: string) {
  const context = React.useContext(ToggleGroupContext);
  if (!context) {
    throw new Error(`${component} must be used inside ToggleGroup.`);
  }
  return context;
}

function isItemPressed(
  type: "single" | "multiple",
  value: string | string[] | undefined,
  itemValue: string,
) {
  if (type === "multiple") {
    return Array.isArray(value) && value.includes(itemValue);
  }
  return value === itemValue;
}

export const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(
  (
    {
      className,
      variant = "default",
      size = "md",
      pressed,
      defaultPressed = false,
      disabled,
      onPressedChange,
      onClick,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const isControlled = pressed !== undefined;
    const [uncontrolledPressed, setUncontrolledPressed] =
      React.useState(defaultPressed);
    const isPressed = isControlled ? pressed : uncontrolledPressed;

    const handleClick = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        const nextPressed = !isPressed;
        if (!isControlled) setUncontrolledPressed(nextPressed);
        onPressedChange?.(nextPressed);
        onClick?.(event);
      },
      [isControlled, isPressed, onClick, onPressedChange],
    );

    return (
      <button
        ref={ref}
        type={type}
        aria-pressed={isPressed}
        data-slot="toggle"
        data-state={isPressed ? "on" : "off"}
        disabled={disabled}
        className={toggleVariants({
          variant,
          size,
          pressed: isPressed,
          className,
        })}
        onClick={handleClick}
        {...props}
      />
    );
  },
);

Toggle.displayName = "Toggle";

export function ToggleGroup({
  type = "single",
  value,
  defaultValue,
  onValueChange,
  variant = "default",
  size = "md",
  orientation = "horizontal",
  disabled,
  children,
  className,
  ...props
}: ToggleGroupProps) {
  const isControlled = value !== undefined;
  const [uncontrolledValue, setUncontrolledValue] = React.useState<
    string | string[] | undefined
  >(defaultValue);
  const selectedValue = isControlled ? value : uncontrolledValue;
  const segmented = type === "single";

  const setValue = React.useCallback(
    (itemValue: string) => {
      if (type === "multiple") {
        const current = Array.isArray(selectedValue) ? selectedValue : [];
        const next = current.includes(itemValue)
          ? current.filter((entry) => entry !== itemValue)
          : [...current, itemValue];
        if (!isControlled) setUncontrolledValue(next);
        onValueChange?.(next);
        return;
      }

      const next = selectedValue === itemValue ? "" : itemValue;
      if (!isControlled) setUncontrolledValue(next);
      onValueChange?.(next);
    },
    [isControlled, onValueChange, selectedValue, type],
  );

  const context = React.useMemo<ToggleGroupContextValue>(
    () => ({
      type,
      value: selectedValue,
      setValue,
      variant,
      size,
      disabled,
      segmented,
    }),
    [disabled, segmented, selectedValue, setValue, size, type, variant],
  );

  React.useEffect(() => {
    ensureToggleStyles();
  }, []);

  const segmentLayout =
    segmented && typeof selectedValue === "string"
      ? getSegmentIndex(children, selectedValue)
      : null;

  return (
    <ToggleGroupContext.Provider value={context}>
      <div
        role="group"
        data-slot="toggle-group"
        data-type={type}
        data-orientation={orientation}
        className={cn(
          "inline-flex",
          segmented && cn(wensityCardSurfaceClass, "relative rounded-xl p-1"),
          orientation === "horizontal"
            ? segmented
              ? "flex-row items-stretch gap-1"
              : "flex-row flex-wrap items-center gap-2"
            : segmented
              ? "flex-col gap-1"
              : "flex-col items-stretch gap-2",
          className,
        )}
        style={
          segmentLayout
            ? ({
                "--toggle-segment-count": segmentLayout.count,
                "--toggle-segment-index": segmentLayout.index,
              } as React.CSSProperties)
            : undefined
        }
        {...props}
      >
        {segmented && segmentLayout && segmentLayout.count > 0 ? (
          <span
            aria-hidden="true"
            data-slot="toggle-segment-indicator"
            data-orientation={orientation}
            className={cn(
              "pointer-events-none absolute rounded-lg",
              "bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))]",
              "dark:bg-[color-mix(in_srgb,var(--foreground)_13%,var(--background))]",
              "shadow-[0_1px_2px_rgba(0,0,0,0.07),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
              "dark:shadow-[0_1px_2px_rgba(0,0,0,0.36),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
              orientation === "horizontal" ? "top-1 bottom-1 left-1" : "left-1 right-1 top-1",
            )}
            style={
              orientation === "horizontal"
                ? {
                    width:
                      "calc((100% - 0.5rem - (var(--toggle-segment-count) - 1) * 0.25rem) / var(--toggle-segment-count))",
                    transform:
                      "translate3d(calc(var(--toggle-segment-index) * (100% + 0.25rem)), 0, 0)",
                  }
                : {
                    height:
                      "calc((100% - 0.5rem - (var(--toggle-segment-count) - 1) * 0.25rem) / var(--toggle-segment-count))",
                    transform:
                      "translate3d(0, calc(var(--toggle-segment-index) * (100% + 0.25rem)), 0)",
                  }
            }
          />
        ) : null}
        {children}
      </div>
    </ToggleGroupContext.Provider>
  );
}

export const ToggleGroupItem = React.forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(
  (
    {
      value,
      variant,
      size,
      disabled,
      className,
      onClick,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const context = useToggleGroupContext("ToggleGroupItem");
    const itemVariant = variant ?? context.variant;
    const itemSize = size ?? context.size;
    const itemDisabled = disabled || context.disabled;
    const pressed = isItemPressed(context.type, context.value, value);

    const handleClick = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        context.setValue(value);
        onClick?.(event);
      },
      [context, onClick, value],
    );

    return (
      <button
        ref={ref}
        type={type}
        value={value}
        aria-pressed={pressed}
        data-slot="toggle-group-item"
        data-state={pressed ? "on" : "off"}
        data-segmented={context.segmented ? "true" : undefined}
        disabled={itemDisabled}
        className={toggleVariants({
          variant: itemVariant,
          size: itemSize,
          pressed,
          segmented: context.segmented,
          className: cn(
            context.segmented && "min-w-[4.5rem] flex-1",
            groupItemBase,
            className,
          ),
        })}
        onClick={handleClick}
        {...props}
      />
    );
  },
);

ToggleGroupItem.displayName = "ToggleGroupItem";
